 public static List<String> group(String group) { return DEVICES.stream().filter(d->d.group().equals(group)).map(Device::id).toList(); }
 public static List<String> scene() { return DEVICES.stream().filter(d->!d.group().startsWith("staff_")).map(Device::id).toList(); }
 public static List<Device> runtime(net.minecraft.server.level.ServerLevel level){
  List<Device> out=new ArrayList<>();
  for(Device d:DEVICES){Device bound=d;
   // Each family's codec/disk failures are contained. A broken unrelated receipt never prevents OFF.
   try{
    if(d.kind()==Kind.FLOOR_LEVER){
     FloorPositionEnrollment r=FloorPositionEnrollment.read(level);
     if(FloorPositionEnrollment.receiptFault(level,r)==null){var p=AuxiliaryPlan.get(d.id());var e=r.entry(d.id());
      if(p!=null&&p.floor()&&e!=null&&e.valid())bound=new Device(d.id(),d.group(),d.kind(),d.dimension(),p.controller(),null,d.id().endsWith("west")?"west":"east","floor-position",true,e.routeValid(),"explicit fixed positional floor enrollment");
     }
    }else if(d.kind()==Kind.IE_SIGNAL){
     IeInstallationBinding r=IeInstallationBinding.read(level);
     if(IeInstallationBinding.receiptFault(level,r)==null){var c=IeCircuitPlan.get(d.id());var e=r.entry(d.id());
      if(c!=null&&e!=null&&e.valid())bound=new Device(d.id(),d.group(),d.kind(),d.dimension(),c.controller().pos(),c.breaker().pos(),c.controller().facing(),e.owner(),true,e.routeValid(),"explicitly bound installation");
     }
    }
   }catch(RuntimeException|LinkageError familyUnavailable){bound=d;}
   out.add(bound);
  }
  return List.copyOf(out);
 }
